for index, (tag, prompt, opts, answer, reason) in enumerate(DATA, 1):
    record = json.loads((OUT / f'question-science-content-ma-iv-5-{index}.json').read_text())
    correct_index = opts.index(answer)
    target = TARGET_ANSWERS[index - 1]
    distractors = [text for option_index, text in enumerate(opts) if option_index != correct_index]
    position = ord(target) - 65
    arranged = distractors[:position] + [answer] + distractors[position:]
    record.update({'prompt': prompt, 'options': [{'id': chr(65 + i), 'text': text} for i, text in enumerate(arranged)], 'answer': {'value': target, 'explanation': reason + f' 正確答案為選項 {target}：「{answer}」。'}, 'solutionStrategy': '先把在地現象連到可測量的暴露、環境條件與健康結果，再用對照、長期資料、方法透明及居民參與檢查結論。', 'solutionSteps': [f'讀題定位：圈出「{tag}」與題目要求判斷的地方現象或健康證據。', f'建立判準：{reason}', f'核對答案：選項 {target}「{answer}」符合判準。', '排除誘答：檢查是否只有單次觀察、單一感受或過度保證，並補回必要的對照、方法與不確定性。', f'最後回查：確認「{answer}」的資料足以支持題目要求的在地決策。'], 'reviewStatus': 'draft', 'updatedAt': '2026-09-13', 'provenance': {**record.get('provenance', {}), 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究本土科學知能與社會、環境、健康決策的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}})
    record['examPatternRefs'] = [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '本土科學知能與社會、環境、健康決策', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}]
    (OUT / f'question-science-content-ma-iv-5-{index}.json').write_text(json.dumps(record, ensure_ascii=False, indent=2) + '\n')
print('rewrote', len(DATA), 'questions')
